WITH ops AS (SELECT o.operation_id,s.service_code,o.route_id FROM logical_operations o JOIN service_routes r USING(route_id) JOIN services s USING(service_id) WHERE opened_at_ms>=1777629600000 AND opened_at_ms<1777633200000), ag AS (SELECT op.operation_id,count(a.attempt_id) attempts,sum(CASE WHEN f.is_success=0 THEN 1 ELSE 0 END) failed_attempts,max(a.attempt_no) max_no FROM ops op JOIN attempt_events a USING(operation_id) JOIN failure_codes f USING(code_id) GROUP BY op.operation_id), terminal AS (SELECT a.operation_id, CASE WHEN f.is_success=0 THEN 1 ELSE 0 END fail FROM attempt_events a JOIN failure_codes f USING(code_id) WHERE (a.operation_id,a.attempt_no) IN (SELECT operation_id,max(attempt_no) FROM attempt_events GROUP BY operation_id)) SELECT service_code,count(*) operations,sum(attempts) attempts,sum(failed_attempts) failed_attempts,sum(fail) terminal_failures,sum(attempts>1) retried_operations FROM ops JOIN ag USING(operation_id) JOIN terminal USING(operation_id) GROUP BY service_code;
SQL

